    # and having no known path to start with.
    # The list to store the current showing known distance to reach the node and full path with to and from nodes.
    distances = {node: float('inf') for node in graph}
    previous_nodes = {node: None for node in graph}
    distances[source] = 0

    # Step 2: Perform the Dijkstra's algorithm
    from heapq import heappop, heappush
    import math

    def dijkstra():
        priority_queue = [(0, source)]  # (distance, node)
        while priority_queue:
            current_distance, node = heappop(priority_queue)
            if current_distance > distances[node]:
                continue
            if node == target:
                # Step 3: Reconstruct the shortest path from target to source
                path = []
                while node:
                    path.append(node)
                    node = previous_nodes[node]
                path.reverse()
                return distances[target], path
            for neighbor, weight in graph.get(node, []):
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    previous_nodes[neighbor] = node
                    heappush(priority_queue, (distance, neighbor))
        # Step 4: If there is no path from source to target, return infinity and None
        return float('inf'), None

    return dijkstra()
