def shortest_path(graph, source, target):
    # Step 1: Prebuild the distance table with the longest possible distance, which is the first step of the improved version of the shortest path with 7 steps.
    # The distance between non-connected nodes should be 0.
    # It's also worth mentioning that the distance from the source to itself is 0.
    distance_table = {node: float('inf') for node in graph}
    distance_table[source] = 0

    # Step 2: Implement the Floyd-Warshall algorithm, which is a more general algorithm for finding the shortest paths between all pairs of nodes.
    # The algorithm is an all-pairs shortest path algorithm, meaning that for each pair of nodes (u, v), it returns the shortest path between u and v.
    for node in graph:
        for neighbor, weight in graph[node]:
            if distance_table[node] + weight < distance_table[neighbor]:
                distance_table[neighbor] = distance_table[node] + weight

    # Step 3: Check the shortest path from source to target.
    if distance_table[target] == float('inf'):
        return float('inf'), None
    else:
        # Step 4: Backtrack to find the actual path.
        path = []
        current_node = target
        while current_node != source:
            for neighbor, weight in graph[current_node]:
                if distance_table[neighbor] == distance_table[current_node] - weight:
                    path.append(current_node)
                    current_node = neighbor
                    break
        path.append(source)
        path.reverse()
        return distance_table[target], path

